 @Test void configurationExplicitSadContextAndDirectGuardMatrix() throws Exception {actor("PRO","CLINIC","HUMAN");assertEquals(403,assertThrows(ApiException.class,()->store.configuration(request,null)).status);assertEquals(403,assertThrows(ApiException.class,()->store.configuration(request,TENANT)).status);request.removeAttribute("health.tenant");request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",null,List.of("SOP"),"a".repeat(64)));assertEquals(403,assertThrows(ApiException.class,()->store.configuration(request,TENANT)).status);request.setAttribute("health.actor",new Actor(ID,"Synthetic","qa@example.test",null,List.of("SAD"),"a".repeat(64)));assertEquals(400,assertThrows(ApiException.class,()->store.configuration(request,"bad")).status);verifyNoInteractions(executor);var sets=configurationSets();doAnswer(inv->{assertTrue(TransactionSynchronizationManager.isActualTransactionActive());var c=inv.<SqlServerContext>getArgument(1);assertNull(c.tenantId());assertEquals(ID,c.actorId());assertEquals(SqlServerContext.Scope.REQUEST,c.scope());assertEquals(List.of(TENANT),Arrays.asList((Object[])inv.getRawArguments()[2]));return new SqlServerExecutor.Result(sets,List.of());}).when(executor).execute(eq(SqlServerProcedure.ORGANIZATION_CONFIGURATION),any(),any(Object[].class));assertEquals(TENANT,store.configuration(request,TENANT).get("id"));verify(executor,times(1)).execute(any(),any(),any(Object[].class));}
