 @Test void configurationDoesNotApplyCatalogDentalFilterToHistoricalAssignments() throws Exception {String sql;try(var in=getClass().getResourceAsStream("/db/sqlserver/V2__catalog_seed.sql")){sql=new String(in.readAllBytes(),StandardCharsets.UTF_8);}String line=sql.lines().filter(v->v.contains("VALUES(N'H_FAMILY',")).findFirst().orElseThrow();var chunks=java.util.regex.Pattern.compile("N'((?:''|[^'])*)'").matcher(line.substring(line.indexOf("CAST(N'")));var body=new StringBuilder();while(chunks.find())body.append(chunks.group(1).replace("''","'"));var profile=new tools.jackson.databind.ObjectMapper().readValue(body.toString(),Map.class);var sets=configurationSets();sets.get(0).getFirst().put("kind","DENTAL");sets.get(0).getFirst().put("kinds",List.of("DENTAL"));sets.get(0).getFirst().put("modules",List.of("CORE","DENTAL"));sets.get(3).clear();sets.get(3).add(new LinkedHashMap<>(Map.of("code","H_FAMILY","name",profile.get("name"),"domain","HUMAN","dental",false,"profile",profile)));sets.get(2).getFirst().put("specialties",List.of("H_FAMILY"));sets.get(6).getFirst().put("specialtyCode","H_FAMILY");actor("ADM","DENTAL","HUMAN");config(sets);var out=store.configuration(request,null);var specialty=((List<Map<String,Object>>)out.get("specialties")).getFirst();assertEquals(false,specialty.get("dental"));assertEquals(profile,specialty.get("profile"));assertEquals(List.of("H_FAMILY"),((List<Map<String,Object>>)out.get("members")).getFirst().get("specialties"));}
